/* cmd-inspect — safe CMD parser with real SHA-256 verification. */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/stat.h>
#include "../format/cmd-format.h"

typedef struct {uint32_t h[8];uint64_t bits;uint8_t b[64];size_t n;} S;
static const uint32_t K[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b69c1,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
#define R(x,n)((x>>n)|(x<<(32-n)))
#define C(x,y,z)((x&y)^(~x&z))
#define M(x,y,z)((x&y)^(x&z)^(y&z))
#define A(x)(R(x,2)^R(x,13)^R(x,22))
#define B(x)(R(x,6)^R(x,11)^R(x,25))
#define D(x)(R(x,7)^R(x,18)^(x>>3))
#define E(x)(R(x,17)^R(x,19)^(x>>10))
static void si(S*c){uint32_t h[]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memcpy(c->h,h,sizeof h);c->bits=0;c->n=0;}
static void sb(S*c,const uint8_t*p){uint32_t w[64],a,b,d,e,f,g,h,x;int i;for(i=0;i<16;i++)w[i]=((uint32_t)p[4*i]<<24)|((uint32_t)p[4*i+1]<<16)|((uint32_t)p[4*i+2]<<8)|p[4*i+3];for(;i<64;i++)w[i]=E(w[i-2])+w[i-7]+D(w[i-15])+w[i-16];a=c->h[0];b=c->h[1];x=c->h[2];d=c->h[3];e=c->h[4];f=c->h[5];g=c->h[6];h=c->h[7];for(i=0;i<64;i++){uint32_t t=h+B(e)+C(e,f,g)+K[i]+w[i],u=A(a)+M(a,b,x);h=g;g=f;f=e;e=d+t;d=x;x=b;b=a;a=t+u;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=x;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;}
static void su(S*c,const uint8_t*p,size_t n){c->bits+=(uint64_t)n*8;while(n){size_t k=64-c->n;if(k>n)k=n;memcpy(c->b+c->n,p,k);c->n+=k;p+=k;n-=k;if(c->n==64){sb(c,c->b);c->n=0;}}}
static void sf(S*c,uint8_t*o){size_t i=c->n;c->b[i++]=0x80;while(i!=56){if(i==64){sb(c,c->b);i=0;}c->b[i++]=0;}for(int j=0;j<8;j++)c->b[63-j]=(uint8_t)(c->bits>>(8*j));sb(c,c->b);for(i=0;i<8;i++){o[4*i]=(uint8_t)(c->h[i]>>24);o[4*i+1]=(uint8_t)(c->h[i]>>16);o[4*i+2]=(uint8_t)(c->h[i]>>8);o[4*i+3]=(uint8_t)c->h[i];}}
static int rng(long fs,long ho,uint32_t o,uint32_t n){uint64_t a=(uint64_t)ho+o,b=a+n;return b>=a&&b<=(uint64_t)fs;}
static int read_at(FILE*f,void*p,size_t n,long off){if(fseek(f,off,SEEK_SET))return -1;return fread(p,1,n,f)==n?0:-1;}
static long find_header(FILE*f,long fs){uint8_t b[4096];for(long base=0;base<fs;){size_t n=(size_t)((fs-base)>(long)sizeof b?sizeof b:(size_t)(fs-base));if(read_at(f,b,n,base))return -1;for(size_t i=0;i+sizeof(cmd_header_t)<=n;i++){cmd_header_t h;memcpy(&h,b+i,sizeof h);long ho=base+(long)i;if(h.magic==CMD_MAGIC&&h.version==CMD_VERSION&&rng(fs,ho,h.icon_offset,h.icon_size)&&rng(fs,ho,h.manifest_offset,h.manifest_size)&&rng(fs,ho,h.class_offset,h.class_size)&&rng(fs,ho,h.security_offset,h.security_size)&&(!h.native_hint_size||rng(fs,ho,h.native_hint_offset,h.native_hint_size)))return ho;}if(n<sizeof b)break;base+=(long)(n-(CMD_HEADER_SIZE-1));}return -1;}
static int verify(FILE*f,long ho,const cmd_header_t*h){S s;si(&s);uint8_t b[65536],got[32];uint32_t left=h->class_size;long pos=ho+h->class_offset;while(left){size_t n=left>sizeof b?sizeof b:left;if(read_at(f,b,n,pos))return -1;su(&s,b,n);pos+=(long)n;left-=(uint32_t)n;}sf(&s,got);return memcmp(got,h->sha256,32)==0?0:1;}
static void flags(uint16_t f){static const char*n[] = {"EMBEDDED_JAR","EMBEDDED_CLASS","EXTERNAL_REF","NATIVE_IMAGE","PINNABLE","HEADLESS","NEGAMANE","GRAIN_AWARE"};printf("Flags: 0x%04x (",f);int first=1;for(int i=0;i<8;i++)if(f&(1u<<i)){if(!first)printf(" | ");printf("%s",n[i]);first=0;}if(first)printf("none");puts(")");}
static void usage(const char*p){fprintf(stderr,"Usage: %s [--manifest] [--security] [--icon] [--verify] [--all] file.cmd\n",p);}
int main(int ac,char**av){const char*name=NULL;int man=0,sec=0,icon=0,ver=0;for(int i=1;i<ac;i++){if(!strcmp(av[i],"--manifest"))man=1;else if(!strcmp(av[i],"--security"))sec=1;else if(!strcmp(av[i],"--icon"))icon=1;else if(!strcmp(av[i],"--verify"))ver=1;else if(!strcmp(av[i],"--all"))man=sec=icon=ver=1;else if(!strcmp(av[i],"--help")||!strcmp(av[i],"-h")){usage(av[0]);return 0;}else if(av[i][0]!='-')name=av[i];}if(!name){usage(av[0]);return 2;}FILE*f=fopen(name,"rb");if(!f){perror(name);return 1;}fseek(f,0,SEEK_END);long fs=ftell(f);long ho=find_header(f,fs);if(ho<0){fprintf(stderr,"Error: no structurally valid CMD header found\n");fclose(f);return 1;}cmd_header_t h;if(read_at(f,&h,sizeof h,ho)){fprintf(stderr,"Error: truncated CMD header\n");fclose(f);return 1;}printf("=== CMD: %s ===\nFile size: %ld\nHeader offset: 0x%lx\nHeader size: %u\nVersion: %u.%u\n",name,fs,ho,CMD_HEADER_SIZE,h.version>>8,h.version&0xff);flags(h.flags);printf("JDK minimum: %u\n",h.jdk_min_version);printf("Icon:      %u +%u\nManifest:  %u +%u\nClass:     %u +%u\nSecurity:  %u +%u\n",h.icon_offset,h.icon_size,h.manifest_offset,h.manifest_size,h.class_offset,h.class_size,h.security_offset,h.security_size);printf("SHA-256: ");for(int i=0;i<32;i++)printf("%02x",h.sha256[i]);puts("");if(man||sec){char*buf;uint32_t off,n;const char*title;if(man){off=h.manifest_offset;n=h.manifest_size;title="Manifest";}else{off=h.security_offset;n=h.security_size;title="Security";}buf=malloc((size_t)n+1);if(buf&&read_at(f,buf,n,ho+off)==0){buf[n]=0;printf("\n--- %s ---\n%s",title,buf);}free(buf);}if(icon&&h.icon_size){char out[512];snprintf(out,sizeof out,"%s.icon.bmp",name);FILE*o=fopen(out,"wb");if(!o||read_at(f,buf=NULL,0,0)){if(o)fclose(o);}if(o){uint8_t*b=malloc(h.icon_size);if(b&&read_at(f,b,h.icon_size,ho+h.icon_offset)==0)fwrite(b,1,h.icon_size,o);free(b);fclose(o);printf("Icon extracted: %s\n",out);}}if(ver){int r=verify(f,ho,&h);printf("\nVerification:\nSHA-256: %s\nSection bounds: valid\nNEGAMANE: %s\n",r==0?"PASS":"FAIL",(h.flags&CMD_FLAG_NEGAMANE)?"enabled":"not set");if(r!=0){fclose(f);return 1;}}fclose(f);return 0;}
